#!/usr/bin/env bash
# Fetch real-world WebP benchmark inputs that are NOT committed to this repo.
#
# The four inputs in webp-inputs/ are generated by generate-webp-inputs.sh, so they are ours and
# small. The files here are someone else's: Google's WebP gallery samples, whose licence is not
# stated, and this repo is Unlicense -- so they are downloaded on demand into webp-inputs/external/
# (git-ignored) rather than checked in. They are also over the 200 KB a committed input is kept under.
#
# Each file is pinned by SHA-256, taken at pin time. A mismatch means upstream changed the file, and a
# benchmark whose input can change underneath it is not comparable run to run, so the script stops
# rather than carrying on with different bytes. The benchmarks that use these files are skipped (not
# failed) when they are absent.
set -euo pipefail

HERE="$(cd "$(dirname "$0")" && pwd)"
OUT="$HERE/webp-inputs/external"
mkdir -p "$OUT"

# name | url | sha256
FILES=(
    # 300x225, 100 frames at 100 ms, loops forever: a full first frame, then mostly partial
    # rectangles alpha-blended over the previous one (a 2x2 cube being turned). 380,850 bytes.
    "gallery-anim-1.webp|https://www.gstatic.com/webp/animated/1.webp|8afc28fef9bba14b5eecbbc6bb8b4379dc96b6ebc3e0845607ced41b7dda337c"
)

for entry in "${FILES[@]}"; do
    IFS='|' read -r name url sha <<< "$entry"
    target="$OUT/$name"
    if [ ! -f "$target" ]; then
        echo "[webp external] downloading $name"
        curl -sSfL "$url" -o "$target.part"
        mv "$target.part" "$target"
    fi
    if ! echo "$sha *$target" | sha256sum -c - > /dev/null 2>&1; then
        echo "[webp external] SHA-256 mismatch for $name -- upstream changed it; refusing to use it." >&2
        rm -f "$target"
        exit 1
    fi
    echo "[webp external] $name ok"
done
